#!/usr/bin/env sh
# -------------------------------------------------------------------
# deploy.sh — AegisCore universal deployment script
#
# Usage:
#   ./scripts/deploy.sh [local|cloud|hybrid]
#
# Prerequisites:
#   - .env file generated by ./scripts/bootstrap-env.sh
#   - docker and docker compose (plugin or v2 standalone)
#
# Environment variables (all optional):
#   IMAGE_SOURCE  — "build" (default) or "pull" for pre-built images
#   AEGISCORE_PORT — override the port (default 8080)
#
# Exit codes:
#   0 — success
#   1 — usage / missing prerequisites
#   2 — deployment failed
#   3 — health check timeout
# -------------------------------------------------------------------
set -eu

# --------------- helpers ---------------
err()  { printf '\033[31m[ERROR]\033[0m %s\n' "$*" >&2; exit 1; }
warn() { printf '\033[33m[WARN]\033[0m  %s\n' "$*" >&2; }
info() { printf '\033[36m[INFO]\033[0m  %s\n' "$*" >&2; }
ok()   { printf '\033[32m[OK]\033[0m    %s\n' "$*" >&2; }

usage() {
    cat >&2 <<'USAGE'
Usage: ./scripts/deploy.sh [local|cloud|hybrid]

  local   — Full local deployment (postgres + redis + api + portal)
  cloud   — Cloud deployment (api + portal only, external DB/Redis)
  hybrid  — Hybrid deployment (local DB + cloud replica + S3 WAL archiving)

Environment:
  IMAGE_SOURCE    build (default) | pull
  AEGISCORE_PORT  override port (default 8080)
USAGE
    exit 1
}

# --------------- argument parsing ---------------
[ $# -eq 1 ] || usage
MODE="$1"
case "$MODE" in
    local|LOCAL)   MODE="local" ;;
    cloud|CLOUD)   MODE="cloud" ;;
    hybrid|HYBRID) MODE="hybrid" ;;
    *) usage ;;
esac
info "Deployment mode: $MODE"

# --------------- prerequisites ---------------
[ -f .env ] || err ".env not found. Run ./scripts/bootstrap-env.sh first."

DEPLOYMENT_MODE="$(grep '^DEPLOYMENT_MODE=' .env | cut -d= -f2- || true)"
if [ "$DEPLOYMENT_MODE" != "$MODE" ]; then
    err ".env DEPLOYMENT_MODE is '$DEPLOYMENT_MODE' but you requested '$MODE'. Re-run bootstrap-env.sh or use the matching mode."
fi

# Resolve docker compose command
if docker compose version >/dev/null 2>&1; then
    DOCKER_COMPOSE="docker compose"
elif command -v docker-compose >/dev/null 2>&1; then
    DOCKER_COMPOSE="docker-compose"
else
    err "docker compose (plugin) or docker-compose (v2) is required."
fi

IMAGE_SOURCE="${IMAGE_SOURCE:-build}"
PORT="${AEGISCORE_PORT:-8080}"
BASE_URL="http://localhost:${PORT}"

# --------------- compose file selection ---------------
COMPOSE_FILES="-f docker-compose.yml"

case "$MODE" in
    cloud)
        COMPOSE_FILES="$COMPOSE_FILES -f docker-compose.cloud.yml"
        ;;
    hybrid)
        COMPOSE_FILES="$COMPOSE_FILES -f docker-compose.hybrid.yml"
        ;;
esac

info "Using compose files: $COMPOSE_FILES"
info "Image source: $IMAGE_SOURCE"

# --------------- build vs pull ---------------
BUILD_ARG=""
if [ "$IMAGE_SOURCE" = "build" ]; then
    BUILD_ARG="--build"
    ok "Building images from source"
else
    ok "Using pre-built images (pull)"
fi

# --------------- deploy ---------------
info "Starting deployment..."
# shellcheck disable=SC2086
$DOCKER_COMPOSE --env-file .env $COMPOSE_FILES up -d --wait $BUILD_ARG || err "Docker Compose up failed (exit code $?)."

# --------------- wait for postgres (local/hybrid only) ---------------
if [ "$MODE" = "local" ] || [ "$MODE" = "hybrid" ]; then
    info "Waiting for Postgres to be healthy..."
    PG_TIMEOUT=120
    PG_ELAPSED=0
    PG_SERVICE="postgres"
    if [ "$MODE" = "hybrid" ]; then
        PG_SERVICE="postgres-primary"
    fi

    while [ "$PG_ELAPSED" -lt "$PG_TIMEOUT" ]; do
        # shellcheck disable=SC2086
        if $DOCKER_COMPOSE --env-file .env $COMPOSE_FILES ps "$PG_SERVICE" 2>/dev/null | grep -q 'healthy'; then
            ok "Postgres is healthy"
            break
        fi
        sleep 2
        PG_ELAPSED=$((PG_ELAPSED + 2))
    done

    if [ "$PG_ELAPSED" -ge "$PG_TIMEOUT" ]; then
        err "Postgres did not become healthy within ${PG_TIMEOUT}s."
    fi
fi

# --------------- run migrations ---------------
info "Running database migrations..."
# shellcheck disable=SC2086
$DOCKER_COMPOSE --env-file .env $COMPOSE_FILES exec api dotnet ef database update 2>&1 || warn "Migration step reported a non-zero exit. Continuing..."

# --------------- health check ---------------
info "Checking portal health at ${BASE_URL}/api/portal-health ..."
HEALTH_RETRIES=30
HEALTH_INTERVAL=3
retry=0
while [ "$retry" -lt "$HEALTH_RETRIES" ]; do
    if curl -fsS "${BASE_URL}/api/portal-health" >/dev/null 2>&1; then
        ok "Portal is healthy"
        break
    fi
    retry=$((retry + 1))
    if [ "$retry" -ge "$HEALTH_RETRIES" ]; then
        err "Portal health check failed after ${HEALTH_RETRIES} attempts."
    fi
    sleep "$HEALTH_INTERVAL"
done

# --------------- summary banner ---------------
TIMESTAMP="$(date -u +%Y-%m-%dT%H:%M:%SZ)"

echo ""
echo "╔══════════════════════════════════════════════════════════╗"
echo "║              AegisCore Deployment Summary               ║"
echo "╠══════════════════════════════════════════════════════════╣"
printf "║  Mode       : %-42s ║\n" "$MODE"
printf "║  Portal     : %-42s ║\n" "${BASE_URL}"
printf "║  API        : %-42s ║\n" "${BASE_URL}/api"
printf "║  Timestamp  : %-42s ║\n" "$TIMESTAMP"
echo "╚══════════════════════════════════════════════════════════╝"
echo ""

ok "Deployment complete."
exit 0
